//! Java: the JNA bindings in `package com.azul` (`target/codegen/java/`,
//! generated by `doc/src/codegen/v2/lang_java`).
//!
//! Spellings: the raw C functions are static natives on one class per api
//! module, `AzulNative<Module>.Az<Class>_<lowerCamel>(..)` (`AzulNativeCss`,
//! `AzulNativeVec`, `AzulNativeStr`, `AzulNativeWindow`, ...), returning
//! `AzXxx.ByValue`; C-like enums are Java enums without the `Az` prefix whose
//! `.value` is what the natives take (`LayoutDisplay.Flex.value`); structs
//! and unions are JNA `Structure` / `Union` classes with public fields, so a
//! value is built with statements - the generated `AzulCodegen.with(value,
//! v -> { .. })` helper turns them into an expression (a union also needs
//! `setType("Variant")`). A Vec is built by `AzulCodegen.vec`, which copies
//! the items into native `Memory` and calls `AzulNativeVec.AzXxxVec_copyFromPtr`.
//!
//! A DOM goes through the wrapper classes instead (`lang_java/wrappers.rs`):
//! static factories keep the lowerCamel api name (`Dom.createDiv()`,
//! `SmallAriaInfo.label(..)`), a by-value `self` method consumes its
//! receiver and returns a new `Dom` (`.withChild(..)`, chained), and string
//! arguments are `java.lang.String`s. An app is `App.create(data,
//! AppMain::layout)` with a typed layout method
//! (`AzulHostInvoker.LayoutCallbackWithData`).

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{capitalize, lower_first, snake_to_lower_camel, EnumShape, Ident, Item, Module, Prim},
    lang::{
        dom::{is_dom_item, one_line, registration_note, WrapperDom, WrapperDomSyntax},
        escape_quoted, item_comments, item_doc, unicode_utf16, variant_ctor_method, ConcatPart,
        ExprSyntax, MethodLayout,
    },
    lower_types::{api_module, is_c_like_enum},
    CodegenBackend, GeneratedFile,
};

/// The Java printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Java;

const KEYWORDS: &[&str] = &[
    "abstract", "assert", "boolean", "break", "byte", "case", "catch", "char", "class", "const",
    "continue", "default", "do", "double", "else", "enum", "extends", "final", "finally",
    "float", "for", "goto", "if", "implements", "import", "instanceof", "int", "interface",
    "long", "native", "new", "package", "private", "protected", "public", "return", "short",
    "static", "strictfp", "super", "switch", "synchronized", "this", "throw", "throws",
    "transient", "try", "void", "volatile", "while", "var", "record", "yield",
];

fn field(name: &str) -> String {
    if KEYWORDS.contains(&name) {
        format!("{name}_")
    } else {
        name.to_string()
    }
}

/// `AzulNativeCss` for a class of api module `css`.
pub(crate) fn native_class(ty: &str) -> String {
    format!("AzulNative{}", capitalize(api_module(ty).unwrap_or("css")))
}

/// The lambda parameter for a value of type `ty` (unique along a nesting
/// chain: a type never contains itself).
fn var_name(ty: &str) -> String {
    let v = lower_first(ty);
    if KEYWORDS.contains(&v.as_str()) {
        format!("{v}_")
    } else {
        v
    }
}

/// `AzulCodegen.with(new AzX.ByValue(), x -> { x.a = ..; x.b = ..; })`
fn with_block(ty: &str, var: &str, statements: Vec<Doc>, broken: bool) -> Doc {
    Doc::cat(vec![
        Doc::text(format!("AzulCodegen.with(new Az{ty}.ByValue(), {var} -> ")),
        Doc::list("{", statements, " ", "}", true, broken, false),
        Doc::text(")"),
    ])
}

impl ExprSyntax for Java {
    fn int(&self, value: i128, ty: Prim) -> String {
        match ty {
            Prim::U8 | Prim::I8 | Prim::Bool => format!("(byte) {value}"),
            Prim::U16 | Prim::I16 => format!("(short) {value}"),
            Prim::U64 | Prim::I64 | Prim::Usize | Prim::Isize => format!("{value}L"),
            _ => value.to_string(),
        }
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let (t, suffix) = if ty == Prim::F64 { ("Double", "") } else { ("Float", "f") };
        match text {
            "nan" => format!("{t}.NaN"),
            "inf" => format!("{t}.POSITIVE_INFINITY"),
            "-inf" => format!("{t}.NEGATIVE_INFINITY"),
            _ => format!("{text}{suffix}"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        // JNA maps the C `bool` fields to `byte`
        format!("(byte) {}", u8::from(b))
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "AzulCodegen.str(\"{}\")",
            escape_quoted(s, &[], &unicode_utf16)
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(
            format!("{}.Az{class}_{}", native_class(class), snake_to_lower_camel(method)),
            args,
            broken,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("{ty}.{variant}.value")),
            EnumShape::Tagged => Doc::call(
                format!("{}.Az{ty}_{}", native_class(ty), variant_ctor_method(variant)),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let v = var_name(ty);
                let mut st = vec![Doc::text(format!(
                    "{v}.{variant}.tag = (byte) Az{ty}_Tag.{variant}.value;"
                ))];
                if let Some(payload) = args.into_iter().next() {
                    st.push(Doc::cat(vec![
                        Doc::text(format!("{v}.{variant}.payload = ")),
                        payload,
                        Doc::text(";"),
                    ]));
                }
                st.push(Doc::text(format!("{v}.setType(\"{variant}\");")));
                with_block(ty, &v, st, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let v = var_name(ty);
        let st = fields
            .into_iter()
            .map(|(k, d)| {
                Doc::cat(vec![
                    Doc::text(format!("{v}.{} = ", field(&k))),
                    d,
                    Doc::text(";"),
                ])
            })
            .collect();
        with_block(ty, &v, st, broken)
    }

    fn vec(&self, ty: &str, _elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("AzulNativeVec.Az{ty}_create()"));
        }
        let mut args = vec![Doc::text(format!("AzulNativeVec::Az{ty}_copyFromPtr"))];
        args.extend(items);
        Doc::call("AzulCodegen.vec", args, broken)
    }

    fn unsupported(&self, _what: &str) -> Doc {
        Doc::text("null")
    }
}

/// A parameter's Java name.
fn java_param(name: &Ident) -> String {
    field(&name.lower_camel())
}

/// A `java.lang.String` literal.
fn java_str(s: &str) -> String {
    format!("\"{}\"", escape_quoted(s, &[], &unicode_utf16))
}

/// The DOM through the wrapper classes (`Dom`, `SmallAriaInfo`).
#[derive(Debug, Copy, Clone, Default)]
struct JavaDom;

impl WrapperDomSyntax for JavaDom {
    fn base(&self) -> &dyn ExprSyntax {
        &Java
    }

    fn native_string(&self, s: &str) -> Doc {
        Doc::text(java_str(s))
    }

    fn factory(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("{class}.{}", snake_to_lower_camel(method)), args, broken)
    }

    fn method(&self, recv: Doc, _class: &str, method: &str, args: Vec<Doc>, layout: MethodLayout) -> Doc {
        Doc::chained(
            recv,
            Doc::call(format!(".{}", snake_to_lower_camel(method)), args, layout.args_tall),
        )
    }

    fn param(&self, name: &Ident) -> Doc {
        Doc::text(java_param(name))
    }

    fn concat(&self, parts: &[ConcatPart<'_>]) -> Doc {
        Doc::text(
            parts
                .iter()
                .map(|p| match p {
                    ConcatPart::Lit(s) => java_str(s),
                    ConcatPart::Param(i) => java_param(i),
                })
                .collect::<Vec<_>>()
                .join(" + "),
        )
    }

    fn item_call_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `renderCard("Hi", title)`: another static method of the same class
    /// (named like `dom_item_method` names it).
    fn item_call(&self, item: &Ident, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(item.lower_camel(), args, broken)
    }
}

/// A DOM item: a static method taking its parameters as `String`s.
fn dom_item_method(item: &Item) -> String {
    let syntax = WrapperDom(JavaDom);
    let mut out = String::new();
    for line in &item_comments(&syntax, item) {
        out.push_str(&format!("    // {line}\n"));
    }
    let name = item.name.lower_camel();
    let params = item
        .params
        .iter()
        .map(|p| format!("String {}", java_param(&p.name)))
        .collect::<Vec<_>>()
        .join(", ");
    match item_doc(&syntax, item) {
        Ok(doc) => out.push_str(&format!(
            "    public static Dom {name}({params}) {{\n        return {};\n    }}\n",
            render(&doc, "    ", 2)
        )),
        Err(reason) => out.push_str(&format!(
            "    // not expressible with the Java bindings: {reason}\n    public static Dom \
             {name}({params}) {{\n        return null;\n    }}\n"
        )),
    }
    out
}

/// Why the Java bindings cannot register a component library.
const NO_REGISTRATION: &str = "the Java bindings build neither: ComponentDef and \
                               ComponentLibrary have no public factory, and the host-invoker \
                               callbacks do not cover ComponentRenderFn, a raw function pointer \
                               that returns its ResultStyledDomRenderDomError by value";

/// The class a module's functions live in.
fn module_class(m: &Module) -> &'static str {
    if m.is_dom() {
        "AzulUi"
    } else {
        "AzulStyles"
    }
}

/// The app's `main` around a DOM module (`m.app`). The wrapper layer sets
/// no window title (it is a raw `window_state` field).
fn app_main(m: &Module) -> String {
    let Some(app) = &m.app else {
        return String::new();
    };
    let root = format!("{}.{}()", module_class(m), app.root.lower_camel());
    let body = if app.is_body {
        root
    } else {
        format!("Dom.createBody().withChild({root})")
    };
    format!(
        "// {} - generated by AzBuilder (azul-css codegen, Java).\npackage com.azul;\n\npublic \
         final class AppMain {{\n    private AppMain() {{}}\n\n    // The app's data: the layout \
         callback gets it back.\n    static final class AppData {{}}\n\n    static Dom \
         layout(AppData data, LayoutCallbackInfo info) {{\n        return {body};\n    }}\n\n    \
         public static void main(String[] args) {{\n        try (App app = App.create(new \
         AppData(), AppMain::layout)) {{\n            \
         app.run(WindowCreateOptions.create());\n        }}\n    }}\n}}\n",
        one_line(&app.title)
    )
}

/// The helpers every generated file carries.
const HELPERS: &str = r"final class AzulCodegen {
    private AzulCodegen() {}

    // Runs `init` on `value` and returns it: struct / union literals as expressions.
    static <T> T with(T value, Consumer<T> init) {
        init.accept(value);
        return value;
    }

    // Copies the items into native memory; AzXxxVec_copyFromPtr clones them.
    static <V> V vec(BiFunction<Pointer, Long, V> copy, Structure... items) {
        int size = items[0].size();
        Memory mem = new Memory((long) size * items.length);
        for (int i = 0; i < items.length; i++) {
            items[i].write();
            mem.write((long) i * size, items[i].getPointer().getByteArray(0, size), 0, size);
        }
        return copy.apply(mem, (long) items.length);
    }

    // The same for a Vec of C-like enum values.
    static <V> V vec(BiFunction<Pointer, Long, V> copy, int... items) {
        Memory mem = new Memory(4L * items.length);
        for (int i = 0; i < items.length; i++) {
            mem.setInt(4L * i, items[i]);
        }
        return copy.apply(mem, (long) items.length);
    }

    static AzString.ByValue str(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        Memory mem = new Memory(Math.max(1, bytes.length));
        mem.write(0, bytes, 0, bytes.length);
        return AzulNativeStr.AzString_fromUtf8(mem, bytes.length);
    }
}
";

fn item_method(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Java, item) {
        out.push_str(&format!("    // {line}\n"));
    }
    let name = item.name.lower_camel();
    let ty = if is_c_like_enum(&item.ty) {
        "int".to_string()
    } else {
        format!("Az{}.ByValue", item.ty)
    };
    match item_doc(&Java, item) {
        Ok(doc) => out.push_str(&format!(
            "    public static {ty} {name}() {{\n        return {};\n    }}\n",
            render(&doc, "    ", 2)
        )),
        Err(reason) => out.push_str(&format!(
            "    // not expressible with the Java bindings: {reason}\n    public static {ty} \
             {name}() {{\n        return null;\n    }}\n"
        )),
    }
    out
}

impl CodegenBackend for Java {
    fn lang(&self) -> &'static str {
        "java"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["jvm", "scala"]
    }

    fn display_name(&self) -> &'static str {
        "Java"
    }

    fn extension(&self) -> &'static str {
        "java"
    }

    fn exports_dom(&self) -> bool {
        true
    }

    fn emit_module(&self, m: &Module) -> String {
        // The raw-layer helpers (and their imports) serve CSS values only.
        let css = !m.is_dom() || m.items.iter().any(|i| !is_dom_item(i));
        let class = module_class(m);
        let mut out =
            String::from("// Generated by azul-css codegen (Java). Do not edit by hand.\npackage com.azul;\n");
        if css {
            out.push_str(
                "\nimport com.sun.jna.Memory;\nimport com.sun.jna.Pointer;\nimport \
                 com.sun.jna.Structure;\nimport java.nio.charset.StandardCharsets;\nimport \
                 java.util.function.BiFunction;\nimport java.util.function.Consumer;\n",
            );
        }
        out.push_str(&format!(
            "\npublic final class {class} {{\n    private {class}() {{}}\n"
        ));
        for item in &m.items {
            out.push('\n');
            if is_dom_item(item) {
                out.push_str(&dom_item_method(item));
            } else {
                out.push_str(&item_method(item));
            }
        }
        out.push_str("}\n");
        if css {
            out.push('\n');
            out.push_str(HELPERS);
        }
        if let Some(lib) = &m.library {
            out.push('\n');
            for line in registration_note(lib, NO_REGISTRATION) {
                out.push_str(&format!("// {line}\n"));
            }
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        if m.app.is_some() {
            return vec![
                GeneratedFile {
                    path: "pom.xml".to_string(),
                    contents: pom("azul-app", "AppMain"),
                },
                GeneratedFile {
                    path: format!("com/azul/{}.java", module_class(m)),
                    contents: self.emit_module(m),
                },
                GeneratedFile {
                    path: "com/azul/AppMain.java".to_string(),
                    contents: app_main(m),
                },
            ];
        }
        let mut main = String::from(
            "package com.azul;\n\npublic final class StylesMain {\n    public static void \
             main(String[] args) {\n",
        );
        for item in &m.items {
            let name = item.name.lower_camel();
            main.push_str(&format!(
                "        AzCssPropertyWithConditionsVec.ByValue {name} = AzulStyles.{name}();\n        \
                 System.out.println(\"{name}: \" + {name}.len + \" properties\");\n"
            ));
        }
        main.push_str("    }\n}\n");
        vec![
            GeneratedFile {
                path: "pom.xml".to_string(),
                contents: pom("azul-styles", "StylesMain"),
            },
            GeneratedFile {
                path: "com/azul/AzulStyles.java".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "com/azul/StylesMain.java".to_string(),
                contents: main,
            },
        ]
    }
}

/// The Maven build of a project whose jar is `artifact` and whose `main` is
/// `com.azul.<main>`.
fn pom(artifact: &str, main: &str) -> String {
    POM.replace("{artifact}", artifact).replace("{main}", main)
}

const POM: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<!-- Build: copy target/codegen/java/*.java into com/azul/, then
     mvn -q package && java -Djna.library.path=<dir of libazul> -cp target/{artifact}-1.0.0.jar:<jna.jar> com.azul.{main} -->
<project xmlns="http://maven.apache.org/POM/4.0.0"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd">
    <modelVersion>4.0.0</modelVersion>
    <groupId>com.azul.generated</groupId>
    <artifactId>{artifact}</artifactId>
    <version>1.0.0</version>
    <packaging>jar</packaging>
    <properties>
        <maven.compiler.source>11</maven.compiler.source>
        <maven.compiler.target>11</maven.compiler.target>
        <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>
    </properties>
    <dependencies>
        <dependency>
            <groupId>net.java.dev.jna</groupId>
            <artifactId>jna</artifactId>
            <version>5.14.0</version>
        </dependency>
    </dependencies>
    <build>
        <sourceDirectory>${project.basedir}</sourceDirectory>
    </build>
</project>
"#;
